function gedDatePlus(days){var d=new Date(Date.now()+days*86400000);return d.getFullYear()+"-"+String(d.getMonth()+1).padStart(2,"0")+"-"+String(d.getDate()).padStart(2,"0")}
function gedSkillTags(subj){var set={},data=GED[subj];["diag","exam"].forEach(function(k){(data[k]||[]).forEach(function(q){if(q.sk)set[q.sk]=1})});return Object.keys(set)}
function gedSkillStats(subj){var tags=gedSkillTags(subj);var log=Array.isArray(S.skillLog)?S.skillLog:[];var out=[];tags.forEach(function(t){var n=0,ok=0;log.forEach(function(e){if(e.skill===t){n++;if(e.ok)ok++}});if(n)out.push({tag:t,n:n,ok:ok,pct:Math.round(ok/n*100)})});out.sort(function(a,b){return a.pct-b.pct});return out}
function gedWeakestSkill(subj){var st=gedSkillStats(subj);return st.length?st[0]:null}
