var gedCardQueue=null,gedCardIdx=0,gedCardFlip=false;
function gedCardKey(c){return "GED· "+c.f}
function gedCardEntry(c){var k=gedCardKey(c);for(var i=0;i<S.srs.length;i++)if(S.srs[i].en===k)return S.srs[i];return null}
function gedCardBuildQueue(subj){var cards=(GED[subj]&&GED[subj].cards)||[];var now=Date.now();var due=[],fresh=[],later=[];cards.forEach(function(c){var e=gedCardEntry(c);if(!e)fresh.push(c);else if(e.due<=now)due.push(c);else later.push(c)});due.sort(function(a,b){return gedCardEntry(a).due-gedCardEntry(b).due});later.sort(function(a,b){return gedCardEntry(a).due-gedCardEntry(b).due});return due.concat(fresh,later)}
function gedGradeCard(c,g){var e=gedCardEntry(c);if(!e){e={en:gedCardKey(c),so:c.s,box:0,due:Date.now()};S.srs.push(e)}srsApplyGrade(e,g);save();gedCardIdx++;gedCardFlip=false;renderAcad()}
