 if(gedCardIdx>=gedCardQueue.length){h+='<div class="card"><h2>'+uiIcon("check")+' '+lng('Waad dhamaysay wareegtan','Round complete')+'</h2><p>'+gedCardQueue.length+' kaar baad eegtay. Kaararku waxay ku jiraan dib-u-eegistaada (Review) — waxay soo noqon doonaan marka waqtigoodu gaaro. / You went through '+gedCardQueue.length+' cards. They are in your Review queue and will come back when due.</p><button class="btn" id="gedCardsAgain">'+uiIcon("repeat")+' '+lng('Mar kale','Go again')+'</button></div>';app.innerHTML=h;tabs();backBind();document.getElementById("gedCardsAgain").addEventListener("click",function(){gedCardQueue=null;gedCardIdx=0;gedCardFlip=false;renderAcad()});return}
 var c=gedCardQueue[gedCardIdx];var e=gedCardEntry(c);
 h+='<div class="card"><p class="small muted">'+uiIcon("layers")+' '+lng('Kaar','Card')+' '+(gedCardIdx+1)+' / '+gedCardQueue.length+(e?' · '+lng('📦 Sanduuq','Box')+' '+e.box:' · '+uiIcon("sparkle")+' '+lng('Cusub','New')+'')+'</p><div id="gedCardFace" class="ged-flash u-ta-center'+(gedCardFlip?' is-flipped':'')+'"><p class="u-t-lg u-mt-1 u-mb-1"><strong>'+esc(gedCardFlip?c.b:c.f)+'</strong></p>'+(gedCardFlip?'<p class="u-mt-2 u-mb-2">'+esc(c.s)+'</p>':'<p class="small muted">'+lng('Taabo si aad u aragto jawaabta','Tap to see the answer')+'</p>')+'</div>';
 if(gedCardFlip)h+='<div class="u-row u-mt-3"><button class="u-grow btn ghost" id="gedGrade0">'+uiIcon("repeat")+' '+lng('Wali waan baranayaa','Still learning')+'</button><button class="u-grow btn" id="gedGrade2">'+uiIcon("check")+' '+lng('Waan aqaan','I know this')+'</button></div>';
 h+='</div>';app.innerHTML=h;tabs();backBind();
 document.getElementById("gedCardFace").addEventListener("click",function(){gedCardFlip=!gedCardFlip;renderAcad()});
 if(gedCardFlip){document.getElementById("gedGrade0").addEventListener("click",function(){gedGradeCard(c,0)});document.getElementById("gedGrade2").addEventListener("click",function(){gedGradeCard(c,2)})}
