function startGedRun(kind){
 var data=GED[gedSubj];var total,lesson=null;
 if(kind==="practice"){var l=data.lessons.filter(function(x){return x.id===gedLesson})[0];if(!l||!l.qs||!l.qs.length)return;total=l.qs.length;lesson=l.id}
 else if(kind==="mock"){if(!data.exam2||!data.exam2.length)return;total=(data.exam.length+data.exam2.length+(data.exam3?data.exam3.length:0))}
 else total=kind==="diag"?data.diag.length:data.exam.length;
 S.stageE.run={kind:kind,subj:gedSubj,lesson:lesson,idx:0,ans:{},endAt:kind==="exam"?Date.now()+data.examMin*60000:kind==="mock"?Date.now()+(data.mockMin||55)*60000:0,total:total};
 save();gedView="run";renderAcad();
}
function gedRunQs(run){var data=GED[run.subj];if(run.kind==="practice"){var l=data.lessons.filter(function(x){return x.id===run.lesson})[0];return l&&l.qs?l.qs:[]}if(run.kind==="mock")return data.exam.concat(data.exam2||[]).concat(data.exam3||[]);return run.kind==="diag"?data.diag:data.exam}
function gedRunPassage(run){var data=GED[run.subj];return run.kind==="diag"?data.diagPassage:data.examPassage}
function renderGedRun(h,tabs){
 var run=S.stageE.run;if(!run){gedView="home";renderGedAcad();return}
 gedSubj=run.subj;var s=GED_SUBJECTS.filter(function(x){return x.id===run.subj})[0];var qs=gedRunQs(run);var q=qs[run.idx];var passage=gedRunPassage(run);
 if(run.seed==null)run.seed=(Date.now()%90000)+11;
 if(!run.ord||typeof run.ord!=="object")run.ord={};
 if(!run.ord[run.idx])run.ord[run.idx]=shuffle(q.o.map(function(_,oi){return oi}),run.seed*31+run.idx*7+q.o.length);
 var ord=run.ord[run.idx];
 if((run.kind==="exam"||run.kind==="mock")&&run.endAt&&Date.now()>=run.endAt){finishGedRun(true);return}
 h+='<button class="btn ghost" id="gedExit">'+lng('← Dugsiga GED','GED Academy')+'</button><div class="card"><h2>'+(run.kind==="exam"?""+uiIcon("clock")+" "+lng("Imtixaan tababar","Timed practice exam")+"":run.kind==="mock"?""+uiIcon("flask")+" "+lng("Imtixaan tijaabo","Mock exam")+"":run.kind==="practice"?""+uiIcon("pen")+" "+lng("Tababar cashir","Lesson practice")+"":""+uiIcon("search")+" "+lng("Hubinta bilowga","Diagnostic")+"")+' — '+esc(s.en)+'</h2><p><span class="tlight a">'+uiIcon("alert")+' '+esc(lng(UNOFFICIAL_SO,UNOFFICIAL_EN))+'</span> <span class="pill">'+lng('Su\'aal','Question')+' '+(run.idx+1)+' / '+qs.length+'</span>'+((run.kind==="exam"||run.kind==="mock")?'<span class="pill" id="gedTimer">'+uiIcon("clock")+' —</span>':"")+'</p><div class="progress"><i style="width:'+Math.round(run.idx/qs.length*100)+'%"></i></div>';
 if(passage&&(run.subj==="rla"))h+='<details '+(run.idx<5?"open":"")+' class="u-mt-3 u-mb-3"><summary>'+uiIcon("book")+' '+lng('Tudaca akhriska','Reading passage')+'</summary><p class="u-t-lg">'+esc(passage.en)+'</p><p class="muted">'+esc(passage.so)+'</p></details>';
 h+='<p class="u-t-lg u-mt-3"><strong>'+esc(q.q)+'</strong></p>'+(q.qSo?'<p class="muted">'+esc(q.qSo)+'</p>':"");
 h+='<div class="opts">'+ord.map(function(oi,di){return '<button class="opt '+(run.ans[run.idx]===oi?"sel":"")+'" data-gans="'+di+'">'+esc(q.o[oi])+'</button>'}).join("")+'</div>';
 h+='<div class="u-row u-mt-4 u-wrap">'+(run.idx>0?'<button class="btn secondary" id="gedPrev">'+lng('← Dib','Back')+'</button>':"")+(run.idx<qs.length-1?'<button class="btn" id="gedNext">'+lng('Su\'aasha xigta','Next question →')+'</button>':'<button class="btn amber" id="gedFinish">'+lng('Dhammee oo arag natiijada','Finish and see results')+'</button>')+'</div><p class="small muted">'+lng('Jawaabahaagu way kaydsamaan markaad socoto — waad bixi kartaa oo waad soo noqon kartaa, saacadduna way socotaa.','Your answers are saved as you go — you can leave and come back, and the timer keeps running.')+'</p></div>';
 app.innerHTML=h;tabs();
 document.getElementById("gedExit").addEventListener("click",function(){gedView="home";gedSubj=null;renderAcad()});
 app.querySelectorAll("[data-gans]").forEach(function(b){b.addEventListener("click",function(){run.ans[run.idx]=ord[+b.dataset.gans];save();renderAcad()})});
 var pv=document.getElementById("gedPrev");if(pv)pv.addEventListener("click",function(){run.idx--;save();renderAcad()});
 var nx=document.getElementById("gedNext");if(nx)nx.addEventListener("click",function(){run.idx++;save();renderAcad()});
 var fn=document.getElementById("gedFinish");if(fn)fn.addEventListener("click",function(){finishGedRun(false)});
 if(run.kind==="exam"){var tick=function(){var el=document.getElementById("gedTimer");if(!el){clearInterval(gedTimer);gedTimer=null;return}var left=run.endAt-Date.now();if(left<=0){clearInterval(gedTimer);gedTimer=null;finishGedRun(true);return}var m=Math.floor(left/60000),sec=Math.floor(left%60000/1000);el.textContent=lng("⏱️ Waqtiga hadhay","Time left:")+" "+m+":"+(sec<10?"0":"")+sec};tick();gedTimer=setInterval(tick,1000)}
}
function finishGedRun(expired){
 var run=S.stageE.run;if(!run)return;var qs=gedRunQs(run);var score=0;
 qs.forEach(function(q,qi){if(run.ans[qi]!=null&&+run.ans[qi]===q.a)score++});
 var g=gedSubjState(run.subj);
 if(!guestMode){gedFeedMistakes(run.subj,run.kind,qs,run.ans);gedLogCorrect(run.subj,run.kind,qs,run.ans)}
 if(run.kind==="diag"){g.diag={score:score,total:qs.length,date:todayStr()};if(!guestMode)awardBestXP("ged:"+run.subj+":diag",score)}
 else if(run.kind==="practice"){gedFeedMistakes(run.subj,"practice",qs,run.ans);gedLogCorrect(run.subj,"practice",qs,run.ans);var ppct=Math.round(score/qs.length*100);var prev=g.practice[run.lesson];if(!prev||score>prev.score)g.practice[run.lesson]={score:score,total:qs.length,date:todayStr()};if(ppct>=80)g.lessons[run.lesson]=true;if(!guestMode)awardBestXP("ged:"+run.subj+":practice:"+run.lesson,score)}else if(run.kind==="mock"){g.mocks.push({score:score,total:qs.length,date:todayStr()});if(!guestMode)awardBestXP("ged:"+run.subj+":mock",score)}else{g.exams.push({score:score,total:qs.length,date:todayStr()});var epct=Math.round(score/qs.length*100);if(epct>=80){g.mastered={date:todayStr(),pct:epct};g.recheckDue=gedDatePlus(7)}else{g.mastered=null;g.recheckDue=null}if(!guestMode)awardBestXP("ged:"+run.subj+":exam",score)}
 gedResult={subj:run.subj,kind:run.kind,score:score,total:qs.length,qs:qs,ans:JSON.parse(JSON.stringify(run.ans)),expired:!!expired};
 S.stageE.run=null;save();gedView="result";renderAcad();
}
